Contact findOrCreateContactByID(final String id) {
  Contact contact = findContactByID(id);
  if (contact == null) {
    try {
      contact = createVolatileContact(id);
      LOGGER.debug("No existing contact found. Created volatile contact" + " for nick name '" + id + "'.");
    } catch (UnsupportedOperationException | IllegalArgumentException | ClassCastException | NullPointerException e) {
      // Log the error and possibly retry or provide a fallback mechanism
      LOGGER.error("Failed to create volatile contact for ID: " + id, e);
      // Optionally, rethrow the exception or handle it in a different way
    }
  }
  return contact;
}
